function getTopAuthors() {
    // 取评分前85位的作者，按评分降序排列
    const all = [...new Set(getAllReferencePoems().map(p => p.author))]
    return all
        .map(a => ({name: a, rank: authorRanks[a] || 20}))
        .sort((a, b) => b.rank - a.rank || a.name.localeCompare(b.name, 'zh'))
        .slice(0, 85)
        .map(a => a.name);
}function updateAllLists() {
    const r = getAllReferencePoems()
    allAuthors = getTopAuthors()
    allDynasties = [...new Set(r.map(p => p.dynasty))].sort()
    allTypes = [...new Set(r.map(p => p.type))].sort()
    allThemes = [...new Set(r.map(p => p.theme))].sort()
    allBooks = [...new Set(r.map(p => p.book))].sort()
}

let allAuthors = getTopAuthors()
let allDynasties = [...new Set(referencePoems.map(p => p.dynasty))].sort()
let allTypes = [...new Set(referencePoems.map(p => p.type))].sort()
let allThemes = [...new Set(referencePoems.map(p => p.theme))].sort()
let allBooks = [...new Set(referencePoems.map(p => p.book))].sort()

const categoryNames = { 'tang': '唐诗', 'song': '宋词', 'yuan': '元曲', 'ancient': '先秦及其他', 'personal': '个人原创' }

function getCategoryName(c) { return categoryNames[c] || c }

function mapDynastyToCategory(d) {
    if (!d) return 'ancient'
    if (d.includes('唐')) return 'tang'
    if (d.includes('宋')) return 'song'
    if (d.includes('元')) return 'yuan'
    return 'ancient'
}

function initLocalStorage() {
    if (!localStorage.getItem('myPoems')) {
        localStorage.setItem('myPoems', JSON.stringify([
            { id: 'my-1', title: '春日偶成', author: '我', category: 'personal', content: '春风拂面柳丝长，\\n桃花依旧笑人忙。\\n闲看浮云自舒卷，\\n一杯清茗对斜阳。', image: null, createdAt: new Date().toISOString() }
        ]))
    }
}

function getMyPoems() { initLocalStorage(); return JSON.parse(localStorage.getItem('myPoems')) }
function saveMyPoems(p) { localStorage.setItem('myPoems', JSON.stringify(p)) }

function addPoem(poem) {
    const p = getMyPoems()
    poem.id = 'my-' + Date.now()
    poem.createdAt = new Date().toISOString()
    p.unshift(poem)
    saveMyPoems(p)
    return poem
}

function updatePoem(id, data) {
    const p = getMyPoems()
    const i = p.findIndex(x => x.id === id)
    if (i !== -1) { p[i] = { ...p[i], ...data, updatedAt: new Date().toISOString() }; saveMyPoems(p); return p[i] }
    return null
}

function deletePoem(id) { saveMyPoems(getMyPoems().filter(p => p.id !== id)) }

function getPoemById(id, r) {
    if (r) return getAllReferencePoems().find(p => p.id === id)
    return getMyPoems().find(p => p.id === id)
}

function parseJSONPoems(text) {
    try {
        const d = JSON.parse(text)
        if (Array.isArray(d)) return d.map((p, i) => ({
            id: 'import-' + Date.now() + '-' + i,
            title: p.title || p.name || '诗词' + (i + 1),
            author: p.author || '佚名', dynasty: p.dynasty || '未知',
            category: mapDynastyToCategory(p.dynasty),
            type: p.type || '古诗', theme: p.theme || '其他',
            book: p.book || '导入', content: p.content || '',
            image: p.image || null, isImported: true
        }))
    } catch(e) { console.error(e) }
    return []
}

function parseTXTPoems(text) {
    const poems = []
    const lines = text.split('\n').map(l => l.trim()).filter(l => l)
    let current = null, buf = []
    for (const line of lines) {
        if (line.length < 30 && !current) {
            if (current) { current.content = buf.join('\n'); poems.push(current) }
            current = { id: 'import-' + Date.now() + '-' + poems.length, title: line, author: '佚名', dynasty: '未知', category: 'ancient', type: '古诗', theme: '其他', book: '导入', content: '', image: null, isImported: true }
            buf = []
        } else if (current) {
            if ((line.startsWith('——') || line.startsWith('—')) && buf.length === 0) { current.author = line.replace(/[—]/g, '').trim() }
            else { buf.push(line) }
        }
    }
    if (current && buf.length > 0) { current.content = buf.join('\n'); poems.push(current) }
    return poems
}

function importPoems(text, format) {
    format = format || 'auto'
    let poems = []
    if (format === 'auto' || format === 'json') { try { poems = parseJSONPoems(text) } catch(e) { if (format === 'auto') poems = parseTXTPoems(text) } }
    else { poems = parseTXTPoems(text) }
    if (poems.length > 0) { localDBPoems = [...localDBPoems, ...poems]; updateAllLists(); return poems.length }
    return 0
}

function addLocalDBPoems(poems) { localDBPoems = [...localDBPoems, ...poems]; updateAllLists() }
function clearLocalDBPoems() { localDBPoems = []; updateAllLists() }

